import{_ as t,o,c as d,a0 as s}from"./chunks/framework.BDx3ik-m.js";const h=JSON.parse('{"title":"Wildberries TypeScript SDK — Project Status Summary","description":"","frontmatter":{},"headers":[],"relativePath":"PROJECT_STATUS_SUMMARY.md","filePath":"PROJECT_STATUS_SUMMARY.md"}'),r={name:"PROJECT_STATUS_SUMMARY.md"};function a(i,e,n,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="wildberries-typescript-sdk-—-project-status-summary" tabindex="-1">Wildberries TypeScript SDK — Project Status Summary <a class="header-anchor" href="#wildberries-typescript-sdk-—-project-status-summary" aria-label="Permalink to &quot;Wildberries TypeScript SDK — Project Status Summary&quot;">​</a></h1><p><strong>As of:</strong> 2026-08-09 <strong>SDK Version:</strong> 4.1.0 <strong>Status:</strong> 🟢 Production Ready <strong>Source of truth:</strong> <code>package.json</code>, <code>src/index.ts</code>, <code>CHANGELOG.md</code>, <code>backlog/tasks/</code></p><hr><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>The Wildberries TypeScript SDK is a mature, production-ready library providing type-safe access to the Wildberries marketplace API. It is shipped as the npm package <strong><code>daytona-wildberries-typescript-sdk</code></strong> (dual ESM/CJS, Node ≥ 20).</p><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td><strong>Current release</strong></td><td>4.1.0 (2026-07-20)</td></tr><tr><td><strong>Public modules</strong></td><td>14 (<code>sdk.*</code> properties)</td></tr><tr><td><strong>Test suite</strong></td><td>~2,376 tests across 80 test files (default Vitest config)</td></tr><tr><td><strong>Work tracked in Backlog.md</strong></td><td>223 tasks — <strong>all Done</strong> (board cleared)</td></tr><tr><td><strong>OpenAPI source specs</strong></td><td>14 files in <code>wildberries_api_doc/</code> (read-only)</td></tr><tr><td><strong>Build</strong></td><td>Vite (dual ESM/CJS) + <code>vite-plugin-dts</code></td></tr><tr><td><strong>Docs site</strong></td><td>VitePress + TypeDoc, bilingual EN/RU (GitHub Pages)</td></tr></tbody></table><blockquote><p>Numbers above are verifiable from the files listed under &quot;Source of truth.&quot; Legacy &quot;quality score&quot;, &quot;endpoints covered&quot;, and &quot;bundle size&quot; metrics that appeared in earlier versions of this document were not reproducible from CI output and have been removed rather than restated.</p></blockquote><hr><h2 id="how-work-is-tracked-read-this-first" tabindex="-1">How Work Is Tracked (read this first) <a class="header-anchor" href="#how-work-is-tracked-read-this-first" aria-label="Permalink to &quot;How Work Is Tracked (read this first)&quot;">​</a></h2><p>Current and future work is tracked in <strong>Backlog.md</strong> under <code>backlog/tasks/</code>. As of 2026-08-09 the board holds <strong>223 tasks, all with <code>status: Done</code></strong> — the board is cleared and the SDK is production-ready. New work is added as new Backlog.md tasks.</p><p>The older <strong>Epic 1–13 / Story</strong> tracker that lives in <code>docs/stories/</code> and <code>docs/epics/</code> is <strong>historical</strong>. It documents how the SDK was originally built (Infrastructure, Products &amp; Orders, Extended Modules, Promotion Testing, DBS Module, Analytics v3 migration, etc.) and is preserved for reference, but it is <strong>superseded by Backlog.md</strong> as the active source of truth. Do not infer current status from epic percentages — they reflect a past planning cycle, not present reality.</p><hr><h2 id="module-implementation-status" tabindex="-1">Module Implementation Status <a class="header-anchor" href="#module-implementation-status" aria-label="Permalink to &quot;Module Implementation Status&quot;">​</a></h2><p>All 14 public SDK modules are implemented and exposed on the <code>WildberriesSDK</code> class (verified in <code>src/index.ts</code>). Approximate public-method counts are taken from <code>src/modules/&lt;name&gt;/index.ts</code>.</p><table tabindex="0"><thead><tr><th>#</th><th><code>sdk.*</code> property</th><th>Module class</th><th>Domain</th><th>Methods (~)</th></tr></thead><tbody><tr><td>1</td><td><code>sdk.general</code></td><td>GeneralModule</td><td>common-api</td><td>10</td></tr><tr><td>2</td><td><code>sdk.products</code></td><td>ProductsModule</td><td>content-api</td><td>51</td></tr><tr><td>3</td><td><code>sdk.ordersFBS</code></td><td>OrdersFbsModule</td><td>marketplace-api</td><td>35</td></tr><tr><td>4</td><td><code>sdk.ordersFBW</code></td><td>OrdersFbwModule</td><td>marketplace-api</td><td>12</td></tr><tr><td>5</td><td><code>sdk.ordersDBS</code></td><td>OrdersDbsModule</td><td>marketplace-api</td><td>20</td></tr><tr><td>6</td><td><code>sdk.finances</code></td><td>FinancesModule</td><td>finance-api / statistics-api</td><td>11</td></tr><tr><td>7</td><td><code>sdk.analytics</code></td><td>AnalyticsModule</td><td>seller-analytics-api</td><td>19</td></tr><tr><td>8</td><td><code>sdk.communications</code></td><td>CommunicationsModule</td><td>common-api</td><td>25</td></tr><tr><td>9</td><td><code>sdk.reports</code></td><td>ReportsModule</td><td>statistics-api</td><td>25</td></tr><tr><td>10</td><td><code>sdk.promotion</code></td><td>PromotionModule</td><td>advert-api</td><td>45</td></tr><tr><td>11</td><td><code>sdk.tariffs</code></td><td>TariffsModule</td><td>—</td><td>5</td></tr><tr><td>12</td><td><code>sdk.inStorePickup</code></td><td>InStorePickupModule</td><td>click &amp; collect</td><td>18</td></tr><tr><td>13</td><td><code>sdk.userManagement</code></td><td>UserManagementModule</td><td>common-api</td><td>4</td></tr><tr><td>14</td><td><code>sdk.returns</code></td><td>ReturnsModule</td><td>aggregator (since v3.10.0)</td><td>3</td></tr></tbody></table><p><strong>Total: 283 public methods across the 14 modules.</strong></p><p><strong>Supplemental (not a public <code>sdk.*</code> property):</strong> <code>src/modules/1_0_0/</code> exposes a handful of legacy methods (<code>getContentTags</code>, <code>getAdvAdvert</code>, <code>createAdvFullstat</code>, <code>getAdvFullstats</code>, <code>getCalendarPromotions</code>) used internally/by examples.</p><p><strong>Domain base URLs in use:</strong> common-api, content-api, marketplace-api, finance-api, statistics-api, seller-analytics-api, advert-api.</p><hr><h2 id="core-infrastructure" tabindex="-1">Core Infrastructure <a class="header-anchor" href="#core-infrastructure" aria-label="Permalink to &quot;Core Infrastructure&quot;">​</a></h2><ul><li><strong>BaseClient</strong> (<code>src/client/base-client.ts</code>) — axios-based; injects the <code>Authorization</code> header, configurable timeout, typed error transformation (including RFC 7807 <code>problem+json</code>, <code>BidOutOfRange</code>, 406 <code>WarehouseStocksUpdateBlock</code>), and PII-sanitized debug logging. All modules receive it via dependency injection.</li><li><strong>RateLimiter</strong> (<code>src/client/rate-limiter.ts</code>) — per-endpoint token-bucket; limits are extracted from Swagger descriptions; reduced limits are applied automatically for <code>basic</code>/<code>test</code> tokens.</li><li><strong>RetryHandler</strong> (<code>src/client/retry-handler.ts</code>) — exponential backoff; retries network errors, 5xx, and 429; does <strong>not</strong> retry 401/403/422.</li></ul><p>See <code>.omc/artifacts/doc-ground-truth.md</code> for the full surface (config shape, rate-limit structure, exported error classes, and utility helpers).</p><hr><h2 id="version-trajectory-from-changelog-md" tabindex="-1">Version Trajectory (from CHANGELOG.md) <a class="header-anchor" href="#version-trajectory-from-changelog-md" aria-label="Permalink to &quot;Version Trajectory (from CHANGELOG.md)&quot;">​</a></h2><p>The CHANGELOG is the authoritative history; this is a short summary.</p><ul><li><strong>v4.0.0 (2026-07-11)</strong> — <strong>BREAKING major.</strong> Removed all WB-dead/sunset deprecated surface (7 promotion methods, 12 in-store-pickup shims, the v5 finance report, orders-dbs meta, etc.). Each removed symbol is a compile error pointing at its replacement; see <code>docs/guides/migration-v4.md</code>.</li><li><strong>v4.0.1 (2026-07-12)</strong> — <code>sdk.version</code> is now derived from <code>package.json</code> (previously reported a stale <code>3.15.0</code>).</li><li><strong>v4.1.0 (2026-07-20)</strong> — Added <code>analytics.getItemRatingV2()</code>; deprecated <code>analytics.getItemRating()</code> (v1) and <code>reports.getBannedProductsShadowed()</code> ahead of the WB 2026-07-30 deadline.</li></ul><p>Earlier 3.x minors added DBS support, the returns aggregator, normquery/v1-stats endpoints, batch click-collect migration, conformance audit fixes, supply planning utilities (<code>calculateSupplyCost</code>, <code>compareTariffs</code>), and the Analytics v3 sales-funnel migration.</p><hr><h2 id="test-suite" tabindex="-1">Test Suite <a class="header-anchor" href="#test-suite" aria-label="Permalink to &quot;Test Suite&quot;">​</a></h2><ul><li><strong>Runner:</strong> Vitest 4 + <code>@vitest/coverage-v8</code>; MSW 2 for integration (jsdom).</li><li><strong>Default config:</strong> ~2,376 tests across 80 test files.</li><li><strong>TDD specs:</strong> run separately via <code>npm run test:tdd</code> (~39 files, excluded from the default config).</li><li><strong>Coverage thresholds:</strong> ≥ 90% core infrastructure (<code>src/client/</code>), ≥ 80% modules.</li></ul><p>Run them with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # default suite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:tdd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # TDD specs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # integration suite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # with coverage</span></span></code></pre></div><hr><h2 id="build-tooling" tabindex="-1">Build &amp; Tooling <a class="header-anchor" href="#build-tooling" aria-label="Permalink to &quot;Build &amp; Tooling&quot;">​</a></h2><ul><li><strong>Build system:</strong> Vite (dual ESM/CJS) with <code>vite-plugin-dts</code>.</li><li><strong>Subpath exports</strong> (<code>package.json</code>): <code>.</code> plus <code>./finances</code>, <code>./analytics</code>, <code>./communications</code>, <code>./reports</code> (so module types import without clashing with global <code>Error</code>/<code>Date</code>). Modules without a subpath have no public type path.</li><li><strong>Type checking / linting:</strong> <code>npm run type-check</code>, <code>npm run lint</code>.</li><li><strong>Docs:</strong> TypeDoc API reference + VitePress site (<code>npm run docs:api</code>, <code>npm run docs:build</code>, <code>npm run docs:dev</code>).</li></ul><blockquote><p>Earlier versions of this document quoted specific build-time and bundle-size figures (e.g. &quot;871ms&quot;, &quot;567KB gzipped&quot;). Those were point-in-time measurements, not continuously verified, and have been removed. Run <code>npm run build</code> for current numbers.</p></blockquote><hr><h2 id="next-steps-priorities" tabindex="-1">Next Steps &amp; Priorities <a class="header-anchor" href="#next-steps-priorities" aria-label="Permalink to &quot;Next Steps &amp; Priorities&quot;">​</a></h2><p>The SDK is production-ready and the backlog board is cleared. Ongoing and optional work:</p><ol><li><strong>Wildberries deprecation tracking.</strong> WB continually deprecates and removes endpoints (the v4.0.0 major and the v4.1.0 deprecations are direct results). Ongoing work is reactive: validate WB change notices against the SDK and ship migrations ahead of WB deadlines.</li><li><strong>Documentation maintenance.</strong> Keep the VitePress site, module pages, and examples in sync with the code; close the known gap of a missing <code>docs/modules/user-management.md</code> page if/when prioritized.</li><li><strong>Optional Web API / JWT module (experimental).</strong> A <code>docs/epics/</code> proposal exists for integrating undocumented Web APIs that authenticate with JWT instead of an API key. This would ship as an <code>@experimental</code> module with no backward-compatibility guarantee and is <strong>not started</strong>; it is a candidate for future work, not a committed next release.</li></ol><blockquote><p>Note: v1.0 is not &quot;the next release&quot; — the SDK is already at v4.1.0. Earlier &quot;approved for v1.0 release&quot; wording reflected a past milestone and is no longer accurate.</p></blockquote><hr><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Wildberries TypeScript SDK is a stable, production-ready v4.1.0 library:</p><ul><li>14 public modules covering the Wildberries marketplace API surface.</li><li>~2,376 tests across 80 files in the default suite, plus a separate TDD suite.</li><li>223 tracked Backlog.md tasks, all Done.</li><li>Dual ESM/CJS build, TypeScript strict mode, VitePress + TypeDoc docs (bilingual EN/RU).</li></ul><p>Active work is maintenance and WB-deprecation response, tracked as new Backlog.md tasks.</p><hr><p><strong>Last updated:</strong> 2026-08-09 <strong>Verify any fact against:</strong> <code>package.json</code>, <code>src/index.ts</code>, <code>CHANGELOG.md</code>, <code>backlog/tasks/</code>.</p>`,48)])])}const g=t(r,[["render",a]]);export{h as __pageData,g as default};
